head.b:skin:
/* ===== RESET & BASE STYLES ===== */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Be Vietnam Pro', -apple-system, sans-serif;
  background: radial-gradient(circle at 50% 0, #291e14, #0d0906);
  color: #e8dcc6;
  line-height: 1.6;
  min-height: 100vh;
}
a { color: #e5b36a; text-decoration: none; transition: all 0.2s ease; }
a:hover { color: #f1c40f; }

/* ===== NAVBAR ===== */
.kybien-navbar {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #ffffff;
  padding: 14px 20px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
  position: relative;
  z-index: 10;
  border-bottom: 2px solid #f1c40f;
}
.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.brand-logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Noto Serif TC', serif;
}
.brand-logo span { color: #f1c40f; }

.logo-general-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #c62828;
  color: #ffffff;
  border: 2px solid #f1c40f;
  font-family: 'Noto Serif TC', serif;
  font-weight: 900;
  font-size: 1.15rem;
  box-shadow: 0 0 10px rgba(241,196,15,0.4);
}

.nav-links { display: flex; gap: 20px; list-style: none; align-items: center; }
.nav-links a { color: #ffffff; font-weight: 600; font-size: 0.95rem; }
.nav-links a:hover { color: #f1c40f; }

/* ===== MAIN LAYOUT ===== */
.main-wrapper {
  max-width: 1200px;
  margin: 20px auto 40px auto;
  padding: 0 15px;
}

.content-area {
  width: 100%;
}

/* SECTION HEADER TITLE */
.section-title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid #5a3d22;
  padding-bottom: 10px;
  margin-bottom: 25px;
}
.section-title-bar h2 {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.4rem;
  color: #f1c40f;
  letter-spacing: 1px;
}

/* GRID CÁC THẺ BÀI VIẾT BÌNH VĂN SA TRƯỜNG (TRANG CHỦ) */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 22px;
}

.post-card {
  background: linear-gradient(145deg, #33251a, #20140b);
  border: 1px solid #5a3d22;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 6px 18px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.25s ease, border-color 0.25s ease;
}
.post-card:hover {
  transform: translateY(-4px);
  border-color: #f1c40f;
  box-shadow: 0 8px 25px rgba(241,196,15,0.2);
}
.post-card-tag {
  display: inline-block;
  background: #8b0000;
  color: #f1c40f;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.post-card-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 12px;
  line-height: 1.4;
}
.post-card-title a { color: #f1c40f; }
.post-card-title a:hover { color: #fff; }

.post-card-snippet {
  font-size: 0.9rem;
  color: #a8947d;
  line-height: 1.6;
  margin-bottom: 18px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.btn-read-post {
  background: linear-gradient(135deg, #8b0000, #600000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.88rem;
  padding: 10px 18px;
  border-radius: 8px;
  text-align: center;
  display: block;
  border: 1px solid #a83a1f;
  box-shadow: 0 3px 10px rgba(139,0,0,0.4);
}
.btn-read-post:hover {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #f1c40f !important;
  border-color: #f1c40f;
}

/* CHI TIẾT BÀI VIẾT & TRANG TĨNH SẢNH CỜ (STATIC / ITEM VIEW) */
.single-page-view {
  background: transparent;
  width: 100%;
}
.single-post-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 2rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 20px;
  text-align: center;
  line-height: 1.3;
}

/* STYLING BÌNH LUẬN SA TRƯỜNG */
.comments-section {
  margin-top: 45px;
  padding-top: 30px;
  border-top: 2px solid #5a3d22;
  background: linear-gradient(145deg, #22150c, #140b05);
  padding: 24px;
  border-radius: 12px;
  border: 1px solid #5a3d22;
}
.comments-title {
  font-family: 'Noto Serif TC', serif;
  color: #f1c40f;
  font-size: 1.4rem;
  margin-bottom: 20px;
}

/* STYLING PHÂN TRANG (PAGINATION) */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 35px;
  padding-top: 20px;
  border-top: 1px solid #5a3d22;
}
.blog-pager-newer-link, .blog-pager-older-link, .home-link {
  background: linear-gradient(135deg, #4a3320, #291e14);
  color: #f1c40f !important;
  border: 1px solid #5a3d22;
  padding: 10px 18px;
  border-radius: 8px;
  font-weight: bold;
  font-size: 0.9rem;
  transition: all 0.2s ease;
}
.blog-pager-newer-link:hover, .blog-pager-older-link:hover, .home-link:hover {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #fff !important;
  border-color: #f1c40f;
}

/* FOOTER CHUYÊN NGHIỆP */
footer.kybien-footer {
  text-align: center;
  padding: 25px 20px;
  color: #a8947d;
  font-size: 0.9rem;
  border-top: 1px solid #33251a;
  margin-top: 50px;
  background: #120b06;
}
